namespace sv_b4cbaad383af41a58eff27d961f41386.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the currently selected warehouse
/// and notifies all subscribed components when it changes.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            NotifyStateChanged();
        }
    }

    public string CurrentWarehouseName =>
        Warehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public static IReadOnlyList<Warehouse> Warehouses { get; } = new List<Warehouse>
    {
        new("WH-001", "Warehouse A – East"),
        new("WH-002", "Warehouse B – West"),
        new("WH-003", "Warehouse C – North"),
        new("WH-004", "Warehouse D – South"),
    };

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();

    public void Dispose() => OnChange = null;
}

public record Warehouse(string Id, string Name);

namespace sv_b4cbaad383af41a58eff27d961f41386.Services;

/// <summary>
/// Scoped service (per-circuit) that polls for low-stock alerts and
/// broadcasts results to all subscribed components via an event.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private Timer? _timer;
    private int _subscriberCount;
    private int _lastAlertCount;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
    }

    public int CurrentAlertCount => _lastAlertCount;

    /// <summary>
    /// Fired when new alert data arrives. All subscribed components receive this.
    /// </summary>
    public event Action<int>? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = Random.Shared.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by components to start polling. Uses reference counting so polling
    /// runs only while at least one component is subscribed.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _timer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
        }
    }

    /// <summary>
    /// Called by components when they are disposed or leave visibility.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _timer?.Dispose();
            _timer = null;
        }
    }

    private async void PollCallback(object? state)
    {
        try
        {
            var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
            _lastAlertCount = count;
            OnAlertCountChanged?.Invoke(count);
        }
        catch
        {
            // Swallow exceptions during polling to avoid crashing the timer
        }
    }

    public void Dispose()
    {
        _timer?.Dispose();
        _timer = null;
        OnAlertCountChanged = null;
    }
}

