@using sv_b4cbaad383af41a58eff27d961f41386.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector d-flex align-items-center gap-2">
    <label class="text-white mb-0 small" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            style="max-width: 220px;"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.Warehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.CurrentWarehouseId = newId;
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@using sv_b4cbaad383af41a58eff27d961f41386.Services
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="alert-badge position-relative">
    <span class="bi bi-exclamation-triangle-fill-nav-menu" aria-hidden="true"></span>
    @if (_alertCount > 0)
    {
        <span class="badge bg-danger rounded-pill position-absolute top-0 start-100 translate-middle">
            @_alertCount
        </span>
    }
    else
    {
        <span class="badge bg-success rounded-pill position-absolute top-0 start-100 translate-middle">
            0
        </span>
    }
</span>

@code {
    private int _alertCount;

    protected override void OnInitialized()
    {
        _alertCount = AlertService.CurrentAlertCount;
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
    }

    private void HandleAlertCountChanged(int count)
    {
        _alertCount = count;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
    }
}

@page "/dashboard"
@using sv_b4cbaad383af41a58eff27d961f41386.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard – @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <strong>@WarehouseState.CurrentWarehouseName</strong>
    </div>
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="display-4">
            @if (_alertCount > 0)
            {
                <span class="text-danger">⚠ @_alertCount items below minimum</span>
            }
            else
            {
                <span class="text-success">✓ All stock levels OK</span>
            }
        </p>
        <p class="text-muted small">
            Auto-refreshes every 10 seconds. Last updated: @_lastUpdated.ToString("HH:mm:ss")
        </p>
    </div>
</div>

<div class="card">
    <div class="card-header">Warehouse Info</div>
    <div class="card-body">
        <dl class="row mb-0">
            <dt class="col-sm-3">Warehouse ID</dt>
            <dd class="col-sm-9">@WarehouseState.CurrentWarehouseId</dd>
            <dt class="col-sm-3">Name</dt>
            <dd class="col-sm-9">@WarehouseState.CurrentWarehouseName</dd>
            <dt class="col-sm-3">Alert Polling</dt>
            <dd class="col-sm-9"><span class="badge bg-success">Active</span></dd>
        </dl>
    </div>
</div>

@code {
    private int _alertCount;
    private DateTime _lastUpdated = DateTime.Now;

    protected override void OnInitialized()
    {
        _alertCount = AlertService.CurrentAlertCount;
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
        WarehouseState.OnChange += HandleWarehouseChanged;

        // Start polling when the dashboard becomes visible
        AlertService.StartPolling();
    }

    private void HandleAlertCountChanged(int count)
    {
        _alertCount = count;
        _lastUpdated = DateTime.Now;
        InvokeAsync(StateHasChanged);
    }

    private void HandleWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        // Stop polling when the user leaves the dashboard
        AlertService.StopPolling();
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
        WarehouseState.OnChange -= HandleWarehouseChanged;
    }
}

